// ========================================
// ตรวจสอบ Session + โควต้า 5 ครั้ง/เซสชั่น
// ========================================
const body = $input.first().json.body || {};
const sessionId = body.sessionId || '';

if (!sessionId) {
  return [{ json: { passed: false, reason: 'ไม่พบ sessionId', code: 400 } }];
}

const staticData = $getWorkflowStaticData('global');

if (!staticData.sessions) {
  staticData.sessions = {};
}

const now = Date.now();
const SESSION_TTL = 60 * 60 * 1000;
const QUOTA_LIMIT = 5;

Object.keys(staticData.sessions).forEach(sid => {
  if (now - staticData.sessions[sid].createdAt > SESSION_TTL) {
    delete staticData.sessions[sid];
  }
});

if (!staticData.sessions[sessionId]) {
  staticData.sessions[sessionId] = {
    count: 0,
    createdAt: now
  };
}

const session = staticData.sessions[sessionId];

if (session.count >= QUOTA_LIMIT) {
  return [{
    json: {
      passed: false,
      reason: `ใช้ครบโควต้าแล้ว (${QUOTA_LIMIT} ครั้ง/เซสชั่น)`,
      code: 429,
      used: session.count,
      limit: QUOTA_LIMIT,
      remaining: 0
    }
  }];
}

session.count++;
staticData.sessions[sessionId] = session;

return [{
  json: {
    passed: true,
    sessionId,
    used: session.count,
    limit: QUOTA_LIMIT,
    remaining: QUOTA_LIMIT - session.count,
    topic: body.topic || '',
    context: body.context || '',
    language: body.language || 'th'
  }
}];

// ========================================
// สร้าง Prompt สำหรับ Gemini
// Gemini ใช้ contents[] แทน messages[]
// ========================================
const json = $input.first().json;
const topic = json.topic || 'ไม่ระบุหัวข้อ';
const context = json.context || '';
const language = json.language || 'th';

const isThaiLang = language === 'th';

const fullPrompt = isThaiLang
  ? 'คุณคือผู้เชี่ยวชาญด้านระบบอัตโนมัติและนักเขียนเทคนิคระดับมืออาชีพ ภาษาไทย\n' +
    'ฉันมี n8n automation workflow ชื่อ \"' + topic + '\" ต้องการให้คุณเขียนคำอธิบายและขั้นตอนอย่างมืออาชีพ\n\n' +
    'ข้อมูลโหนดและ Credentials ของ workflow:\n' + (context || 'ไม่ได้ระบุ') + '\n\n' +
    'กรุณาสร้างเนื้อหาทั้งหมดเป็น **ภาษาไทย** โดยมีข้อกำหนดดังนี้อย่างเคร่งครัด:\n' +
    '1. **คีย์ \"description\" ต้องมีความยาว 200-500 คำ** (อธิบายกระบวนการทำงานแบบละเอียด ประโยชน์ ผู้ใช้ที่เหมาะสม ปัญหาที่แก้ไขได้ ตัวอย่างสถานการณ์การใช้งาน และคุณค่าที่ได้รับ — ห้ามย่อกระชับเกินไป ต้องให้ข้อมูลเชิงลึก)\n' +
    '2. **ห้ามแปลชื่อคีย์ใน JSON เด็ดขาด!** ต้องใช้คีย์ภาษาอังกฤษ \"description\" และ \"howToUse\" ตามโครงสร้าง JSON ด้านล่างเท่านั้น\n' +
    '3. ผลลัพธ์ต้องตอบกลับเฉพาะ JSON ที่ถูกต้องสมบูรณ์แบบเท่านั้น ห้ามใส่ markdown block (เช่น ```json) และไม่มีข้อความเกริ่นนำหรือท้ายเรื่องใดๆ ทั้งสิ้น\n\n' +
    '## โครงสร้าง JSON ที่คุณต้องตอบกลับ:\n' +
    '{\n' +
    '  \"description\": \"คำอธิบายความยาว 200-500 คำในภาษาไทย อธิบายอย่างละเอียดว่า workflow ทำอะไร แก้ปัญหาอะไร เหมาะกับใคร และมีขั้นตอนการทำงานอย่างไร...\",\n' +
    '  \"howToUse\": [\"ขั้นตอนที่ 1...\", \"ขั้นตอนที่ 2...\"]\n' +
    '}'
  : 'You are a professional technical writer and automation expert.\n' +
    'I have an n8n automation workflow titled \"' + topic + '\". Write a professional description and setup steps.\n\n' +
    'Workflow node data & credentials:\n' + (context || 'Not specified') + '\n\n' +
    'Generate ALL content in **English** following this structure strictly:\n' +
    '1. **The \"description\" key MUST be 200-500 words long** (detailed, comprehensive, explaining the workflow process, who it\'s for, the problems it solves, use-case scenarios, and the value it brings — do NOT be too brief).\n' +
    '2. The response MUST be valid JSON using the English keys: \"description\" and \"howToUse\".\n' +
    '3. Return ONLY valid JSON. No conversational text, no markdown wrappers (like ```json), just raw JSON.\n\n' +
    '## JSON structure to return:\n' +
    '{\n' +
    '  \"description\": \"Detailed description of 200-500 words in English explaining what the workflow does, problems it solves, who it\'s for, and how it works...\",\n' +
    '  \"howToUse\": [\"Step 1...\", \"Step 2...\"]\n' +
    '}';

return [{
  json: {
    ...json,
    fullPrompt
  }
}];

// ========================================
// Parse ผลลัพธ์จาก Gemini
// Gemini: candidates[0].content.parts[0].text
// ========================================
const response = $input.first().json;
const rawText = response?.candidates?.[0]?.content?.parts?.[0]?.text || '';
const usage = response?.usageMetadata || {};

function unescapeUnicode(str) {
  return str.replace(/\\u([0-9a-fA-F]{4})/g, (match, grp) => {
    return String.fromCharCode(parseInt(grp, 16));
  });
}

function cleanAndParseGeminiResponse(rawText) {
  const cleaned = rawText.replace(/```json|```/g, '').trim();

  // 1. ลอง parse แบบปกติ
  try {
    const parsed = JSON.parse(cleaned);
    if (parsed && typeof parsed === 'object') {
      const keysList = Object.keys(parsed);

      // ค้นหาคีย์สำหรับ description (รองรับภาษาไทยกรณี AI แปลคีย์)
      let descKey = keysList.find(k => k.toLowerCase() === 'description');
      if (!descKey && keysList.length > 0) {
        descKey = keysList.find(k => 
          k.toLowerCase().includes('desc') || 
          k.includes('อธิบาย') || 
          k.includes('รายละเอียด') || 
          k.includes('สรุป')
        );
        if (!descKey) descKey = keysList[0];
      }

      let desc = '';
      if (descKey) {
        const val = parsed[descKey];
        if (typeof val === 'string') {
          desc = val;
        } else if (typeof val === 'object' && val !== null) {
          desc = val.description || val.text || JSON.stringify(val);
        }
      }

      // ค้นหาคีย์สำหรับ howToUse
      let howToUseKey = keysList.find(k => k.toLowerCase() === 'howtouse');
      if (!howToUseKey && keysList.length > 1) {
        howToUseKey = keysList.find(k => 
          k.toLowerCase().includes('use') || 
          k.toLowerCase().includes('how') || 
          k.includes('ขั้นตอน') || 
          k.includes('วิธี')
        );
        if (!howToUseKey) {
          howToUseKey = keysList.find(k => k !== descKey) || keysList[1];
        }
      }

      let steps = [];
      if (howToUseKey) {
        const val = parsed[howToUseKey];
        if (Array.isArray(val)) {
          steps = val.map(s => String(s));
        } else if (typeof val === 'string') {
          steps = [val];
        }
      }

      return {
        description: desc.trim(),
        howToUse: steps
      };
    }
  } catch (e) {
    // พยายามใช้ Regex หาก JSON.parse พัง
  }

  // 2. ใช้ Regex ในการสกัดคีย์ภาษาไทยและคีย์ภาษาอังกฤษ
  let description = '';
  const descRegex = /\"(description|คำอธิบาย|รายละเอียด|สรุป)\"\\s*:\\s*\"([^\"\\\\]*(?:\\\\.[^\"\\\\]*)*)\"/i;
  const descMatch = cleaned.match(descRegex);
  if (descMatch && descMatch[2]) {
    description = unescapeUnicode(descMatch[2])
      .replace(/\\\"/g, '"')
      .replace(/\\n/g, '\n')
      .replace(/\\r/g, '\r')
      .replace(/\\t/g, '\t');
  } else {
    const looseDescRegex = /\"(description|คำอธิบาย|รายละเอียด|สรุป)\"\\s*:\\s*([^,}\\]+)/i;
    const looseDescMatch = cleaned.match(looseDescRegex);
    if (looseDescMatch && looseDescMatch[2]) {
      description = unescapeUnicode(looseDescMatch[2].trim().replace(/^[\"']|[\"']$/g, ''));
    }
  }

  let howToUse = [];
  const howToUseRegex = /\"(howToUse|ขั้นตอน|วิธีใช้งาน|วิธีการใช้งาน)\"\\s*:\\s*\\[([\\s\\S]*?)\\]/i;
  const howToUseMatch = cleaned.match(howToUseRegex);
  if (howToUseMatch && howToUseMatch[2]) {
    const arrayContent = howToUseMatch[2];
    const stringMatches = Array.from(arrayContent.matchAll(/\"([^\"\\\\]*(?:\\\\.[^\"\\\\]*)*)\"/g));
    for (const m of stringMatches) {
      if (m[1]) {
        howToUse.push(
          unescapeUnicode(m[1])
            .replace(/\\\"/g, '"')
            .replace(/\\n/g, '\n')
            .replace(/\\r/g, '\r')
            .replace(/\\t/g, '\t')
        );
      }
    }
  }

  // ถ้าล้มเหลวในการสกัด ให้ทำความสะอาด raw text
  if (!description && !howToUse.length) {
    let plainText = cleaned
      .replace(/\\{([\\s\\S]*?)\\}/g, '$1')
      .replace(/\"(description|คำอธิบาย|รายละเอียด|สรุป)\"\\s*:\\s*/gi, '')
      .replace(/\"(howToUse|ขั้นตอน|วิธีใช้งาน|วิธีการใช้งาน)\"\\s*:\\s*/gi, '')
      .replace(/[\\[\\]\"\\{}]/g, '')
      .replace(/^\\s*,/gm, '')
      .trim();

    description = plainText.split('\n')[0] || plainText;
  }

  return {
    description: description.trim(),
    howToUse: howToUse.filter(Boolean)
  };
}

let parsed = { description: '', howToUse: [] };
try {
  parsed = cleanAndParseGeminiResponse(rawText);
} catch (e) {
  parsed = {
    description: rawText.slice(0, 500),
    howToUse: ['ไม่สามารถ parse ผลลัพธ์ได้ กรุณาลองใหม่']
  };
}

if (!parsed.description || parsed.description.trim() === '') {
  parsed.description = rawText.slice(0, 500);
}

const prevJson = $('ตรวจสอบโควต้า').first().json;

return [{
  json: {
    success: true,
    description: parsed.description || '',
    howToUse: parsed.howToUse || [],
    quota: {
      used: prevJson.used,
      limit: prevJson.limit,
      remaining: prevJson.remaining
    },
    tokenUsage: {
      inputTokens: usage.promptTokenCount || 0,
      outputTokens: usage.candidatesTokenCount || 0,
      totalTokens: usage.totalTokenCount || 0,
      maxTokensAllowed: 2500
    }
  }
}];

// ตรวจสอบ API Key / Token จาก Header
const inputItem = $input.first();
const headers = inputItem.json.headers || {};
const body = inputItem.json.body || {};
const apiKey = headers['x-api-key'] || headers['authorization'] || '';

const VALID_API_KEYS = [
  'your-secret-api-key-1',
  'your-secret-api-key-2'
];

const cleanKey = apiKey.replace('Bearer ', '').trim();

if (!cleanKey || !VALID_API_KEYS.includes(cleanKey)) {
  return [{ json: { passed: false, step: 'credential', reason: 'API Key ไม่ถูกต้องหรือไม่มีสิทธิ์เข้าถึง' } }];
}

// ส่ง body data (ข้อมูลไฟล์) ต่อไปยัง node ถัดไป
return [{ json: { passed: true, apiKey: cleanKey, fileData: body } }];

// ========================================
// อ่านข้อมูลไฟล์จาก JSON body (ส่งมาจาก Next.js)
// ไม่ใช้ binary เพื่อหลีกเลี่ยง encoding issues
// ========================================
const inputJson = $input.first().json;
const fd = inputJson.fileData || inputJson.body || inputJson;

const fileName    = fd.fileName || '';
const mimeType    = fd.mimeType || '';
const fileSize    = fd.fileSize || 0;
const fileContent = fd.fileContent || '';

if (!fileContent) {
  return [{ json: { passed: false, step: 'file_meta', reason: 'ไม่พบเนื้อหาไฟล์ในคำขอ (fileContent ว่าง)' } }];
}

const ext = fileName.toLowerCase().slice(fileName.lastIndexOf('.'));

const allowedExt  = ['.json'];
const allowedMime = ['application/json', 'text/plain'];

if (fileName && !allowedExt.includes(ext)) {
  return [{ json: { passed: false, step: 'file_meta', reason: `นามสกุล ${ext} ไม่อนุญาต ต้องเป็นไฟล์ .json เท่านั้น` } }];
}

if (mimeType && !allowedMime.includes(mimeType)) {
  return [{ json: { passed: false, step: 'file_meta', reason: `MIME type ${mimeType} ไม่ใช่ JSON ที่ถูกต้อง` } }];
}

if (fileName.includes('..') || fileName.includes('/') || fileName.includes('\\')) {
  return [{ json: { passed: false, step: 'file_meta', reason: 'ชื่อไฟล์มีอักขระอันตราย (path traversal)' } }];
}

// เก็บ warnings แทนการ block
const warnings = [];

try {

  const parsed = JSON.parse(fileContent);

  if (!parsed.nodes && !parsed.connections) {
    return [{ json: { passed: false, step: 'file_meta', reason: 'ไฟล์ JSON ไม่ใช่รูปแบบ n8n workflow (ไม่พบ nodes หรือ connections)' } }];
  }

  const scanForSecrets = (text) => {
    if (!text || typeof text !== 'string') return null;
    if (/AIzaSy[A-Za-z0-9_\-]{20,}/.test(text)) return 'ตรวจพบ Google API Key (AIzaSy...)';
    if (/sk-(?:proj-)?[a-zA-Z0-9_\-]{40,}/.test(text)) return 'ตรวจพบ OpenAI API Key (sk-...)';
    if (/sk-ant-[a-zA-Z0-9_\-]{40,}/.test(text)) return 'ตรวจพบ Anthropic API Key';
    if (/AKIA[A-Z0-9]{16}/.test(text)) return 'ตรวจพบ AWS Access Key';
    if (/gh[pso]_[a-zA-Z0-9]{36,}/.test(text)) return 'ตรวจพบ GitHub Token';
    if (/xox[baprs]-[a-zA-Z0-9\-]{10,}/.test(text)) return 'ตรวจพบ Slack Token';
    if (/-----BEGIN[^-]*PRIVATE KEY-----/.test(text)) return 'ตรวจพบ Private Key';
    if (/Bearer\s+eyJ[a-zA-Z0-9_\-]{20,}/.test(text)) return 'ตรวจพบ Bearer JWT Token';
    if (/hf_[a-zA-Z0-9]{20,}/.test(text)) return 'ตรวจพบ Hugging Face Token';
    const urlMatch = /[?&](key|api[-_]?key|token|secret|access[-_]?token|client[-_]?secret|password|passwd|apikey)(?:=|%3D|\\u003d)([A-Za-z0-9_\-]{10,})/i.exec(text);
    if (urlMatch) return 'ตรวจพบ API Key/Secret ใน URL Parameter (' + urlMatch[1] + ')';
    return null;
  };

  const isSafeValue = (val) => {
    if (typeof val !== 'string') return true;
    const v = val.trim();
    if (v.length === 0 || v.length < 6) return true;
    if (/^\{\{.*\}\}$/.test(v) || /^=\{\{.*\}\}$/.test(v) || v.startsWith('={{')) return true;
    if (/^(your[_-]|example[_-]|test[_-]|dummy[_-]|fake[_-]|sample[_-]|placeholder|changeme|xxx|TODO|CHANGE_ME|INSERT_HERE|REPLACE_ME)$/i.test(v)) return true;
    if (/^your[_-]?(secret|api|key|token|password)/i.test(v)) return true;
    if (/^(true|false|null|undefined|none|0|1)$/i.test(v)) return true;
    if (/^https?:\/\//i.test(v) && !/[?&](key|token|secret|password|api_key|apikey)=/i.test(v)) return true;
    if (/^\$/.test(v)) return true;
    if (/^(headers|process\.env|req\.|request\.)/.test(v)) return true;
    return false;
  };

  // ---- Step 1: raw regex scan ทั้งไฟล์ ----
  const rawResult = scanForSecrets(fileContent);
  if (rawResult) {
    warnings.push(rawResult + ' ในไฟล์โดยตรง — กรุณาใช้ Credentials ของ n8n แทน');
  }

  // ---- Step 2: deep scan แต่ละ node ----
  if (Array.isArray(parsed.nodes)) {
    for (const node of parsed.nodes) {
      const nodeName = node.name || node.id || 'unknown';

      // 2a. regex scan on parameters
      const paramResult = scanForSecrets(JSON.stringify(node.parameters || {}));
      if (paramResult) {
        warnings.push(paramResult + ' (node: ' + nodeName + ')');
      }

      // 2b. credentials field - ตรวจสอบ secret โดยละเว้น credential ID
      if (node.credentials && typeof node.credentials === 'object') {
        const credsToScan = {};
        for (const [credType, credVal] of Object.entries(node.credentials)) {
          if (credVal && typeof credVal === 'object') {
            const { id, ...rest } = credVal;
            credsToScan[credType] = rest;
          } else {
            credsToScan[credType] = credVal;
          }
        }
        const credResult = scanForSecrets(JSON.stringify(credsToScan));
        if (credResult) {
          warnings.push(credResult + ' (credentials ของ node: ' + nodeName + ')');
        }
      }

      // 2c. meta / typeOptions scan
      const metaResult = scanForSecrets(JSON.stringify({ meta: node.meta, typeOptions: node.typeOptions }));
      if (metaResult) {
        warnings.push(metaResult + ' (meta ของ node: ' + nodeName + ')');
      }
    }
  }

} catch (e) {
  return [{ json: { passed: false, step: 'file_meta', reason: 'ไฟล์ไม่ใช่ JSON หรือเนื้อหาเสียหาย: ' + e.message } }];
}

return [{
  json: {
    passed: true,
    fileName,
    fileSize,
    mimeType,
    ext,
    warnings
  }
}];

